/**
 * Pure classifier for one Stripe failure shape that lib/stripe-cards.ts's
 * `classifyChargeError` used to mis-file as "transient".
 *
 * Stripe refuses a saved PaymentMethod id FOREVER once it has been used on a
 * PaymentIntent without a Customer, or detached from one:
 *   "The provided PaymentMethod was previously used with a PaymentIntent without
 *    Customer attachment or was detached from a Customer. It may not be used again."
 * It arrives as `invalid_request_error` WITHOUT the `resource_missing` code, so
 * the default-transient rule retried it every hour for ever. Observed live
 * 2026-09-30 → 10-01 (docs/AUDIT-7D-2026-10-01.md F-09): 16 identical
 * "[billing] transient charge error" retries for one server, no customer
 * notification, server already past its expiry. Nothing about the customer's
 * bank went wrong, but nothing will change until a NEW card is saved — exactly
 * the existing `unavailable` path (clear the dead card, tell the customer).
 *
 * Kept in its own module (no Stripe/db imports) so it is unit-testable.
 */
export type StripeErrorShape = { rawType?: string; code?: string; message?: string } | null | undefined;

export function isPermanentlyUnusablePaymentMethod(err: StripeErrorShape): boolean {
  if (!err || err.rawType !== "invalid_request_error") return false;
  if (err.code === "payment_method_unexpected_state" || err.code === "payment_method_unattached") return true;
  const m = (err.message ?? "").toLowerCase();
  return (
    m.includes("may not be used again") ||
    m.includes("without customer attachment") ||
    m.includes("was detached from a customer")
  );
}

