import { test } from "node:test";
import assert from "node:assert/strict";
import { isPermanentlyUnusablePaymentMethod } from "../lib/stripe-error-class";

// The exact message the worker logged 16 times in a row for one server
// (journalctl -u nxeon-worker, 2026-09-30 14:50 → 2026-10-01 05:30, hourly):
const LIVE_MESSAGE =
  "The provided PaymentMethod was previously used with a PaymentIntent without Customer attachment or was detached from a Customer. It may not be used again. To use a PaymentMethod multiple times, you must attach it to a Customer first.";

test("the live 'may not be used again' invalid_request_error is permanent, not transient", () => {
  assert.equal(
    isPermanentlyUnusablePaymentMethod({ rawType: "invalid_request_error", message: LIVE_MESSAGE }),
    true,
  );
});

test("known permanent payment_method codes are permanent regardless of message", () => {
  assert.equal(isPermanentlyUnusablePaymentMethod({ rawType: "invalid_request_error", code: "payment_method_unexpected_state" }), true);
  assert.equal(isPermanentlyUnusablePaymentMethod({ rawType: "invalid_request_error", code: "payment_method_unattached" }), true);
});

test("other invalid_request_errors stay on the default (transient) path", () => {
  assert.equal(
    isPermanentlyUnusablePaymentMethod({ rawType: "invalid_request_error", code: "parameter_invalid_integer", message: "Invalid integer: abc" }),
    false,
  );
  assert.equal(isPermanentlyUnusablePaymentMethod({ rawType: "invalid_request_error", message: "" }), false);
});

test("card errors, API errors and non-Stripe errors are never claimed by this classifier", () => {
  // A card_error with the same words must still be a decline, handled earlier.
  assert.equal(isPermanentlyUnusablePaymentMethod({ rawType: "card_error", message: LIVE_MESSAGE }), false);
  assert.equal(isPermanentlyUnusablePaymentMethod({ rawType: "api_error", message: LIVE_MESSAGE }), false);
  assert.equal(isPermanentlyUnusablePaymentMethod({ message: LIVE_MESSAGE }), false);
  assert.equal(isPermanentlyUnusablePaymentMethod(null), false);
  assert.equal(isPermanentlyUnusablePaymentMethod(undefined), false);
});

